from collections import deque
def shortest_path(grid):
    if not grid or not grid[0] or grid[0][0] == 1:
        return -1
    rows, cols = len(grid), len(grid[0])
    queue = deque([(0, 0, 1)])
    visited = {(0, 0)}
    while queue:
        r, c, steps = queue.popleft()
        if r == rows - 1 and c == cols - 1:
            return steps
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
